+ function extractDtsInput(node: ts.Node, metadataReader: DtsMetadataReader): ExtractedInput | null {
+   if (
+     !isInputContainerNode(node) ||
+     !ts.isIdentifier(node.name) ||
+     !node.getSourceFile().isDeclarationFile
+   ) {
+     return null;
+   }
