+     new Reference(node.parent as ClassDeclaration),
+   );
+   const inputMapping = directiveMetadata?.inputs.getByClassPropertyName(node.name.text);
+ 
+   // Signal inputs are never tracked and migrated.
+   if (inputMapping?.isSignal) {
+     return null;
+   }
