+   node: ts.Node,
+   host: MigrationHost,
+   reflector: ReflectionHost,
+   evaluator: PartialEvaluator,
+   refEmitter: ReferenceEmitter,
+ ): ExtractedInput | null {
+   if (
+     !isInputContainerNode(node) ||
+     !ts.isIdentifier(node.name) ||
+     node.getSourceFile().isDeclarationFile
+   ) {
+     return null;
+   }
