+ function extractFunctionWithOverloads(
+     name: string, signatures: readonly ts.Signature[],
+     typeChecker: ts.TypeChecker): FunctionWithOverloads {
+   return {
+     name,
+     signatures:
+         filterSignatureDeclarations(signatures)
