+     // Use `string` here so that it's a usable index key.
+     [inputIdKey: string]: {
+       isIncompatible:
+         | {kind: IncompatibilityType.VIA_CLASS; reason: ClassIncompatibilityReason}
+         | {kind: IncompatibilityType.VIA_INPUT; reason: InputIncompatibilityReason}
+         | null;
+     };
