+ interface Token {
+   type: TokenType;
+   value: string;
+   idx: number;
+ }
+ 
+ const TERMINAL_CHAR = ['[', ']', '<', '>', '/', ' '];
+ const CHAR_TO_TOKEN: {[key: string]: TokenType} = {
+   '[': 'opening_bracket',
+   ']': 'closing_bracket',
+   '<': 'chevron_left',
+   '>': 'chevron_right',
+   '/': 'slash',
+   ' ': 'space',
